// AUTO-GENERATED from ui.html by scripts/build-ui.mjs - do not edit by hand.
export default "<!DOCTYPE html>\n<html lang=\"zh-Hant\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Anima 工作站</title>\n<style>\n  :root{--bg:#0b0d12;--panel:#141821;--panel2:#1b2130;--line:#242c3d;--text:#e6e9f0;--muted:#8b93a7;--ok:#3ddc97;--warn:#f5a524;--bad:#ff5d5d;--accent:#5b8cff}\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--bg);color:var(--text);font:14px/1.5 ui-sans-serif,system-ui,\"Noto Sans TC\",sans-serif}\n  a{color:var(--accent)}\n  .wrap{max-width:1100px;margin:0 auto;padding:20px}\n  header{display:flex;align-items:center;gap:12px;margin-bottom:18px}\n  header h1{font-size:18px;margin:0;font-weight:600}\n  .badge{font-size:12px;padding:2px 8px;border-radius:999px;background:var(--panel2);color:var(--muted)}\n  .grid{display:grid;grid-template-columns:340px 1fr;gap:16px}\n  @media(max-width:860px){.grid{grid-template-columns:1fr}}\n  .card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px}\n  .card h2{font-size:13px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:0 0 12px}\n  label{display:block;font-size:12px;color:var(--muted);margin:10px 0 4px}\n  input,textarea,select,button{font:inherit;color:var(--text)}\n  input[type=text],input[type=password],input[type=number],textarea,select{width:100%;background:var(--panel2);border:1px solid var(--line);border-radius:9px;padding:8px 10px}\n  textarea{resize:vertical;min-height:74px}\n  .row{display:flex;gap:8px}\n  .row>*{flex:1}\n  button{cursor:pointer;border:1px solid var(--line);background:var(--panel2);border-radius:9px;padding:9px 14px}\n  button.primary{background:var(--accent);border-color:transparent;color:#fff;font-weight:600}\n  button:disabled{opacity:.5;cursor:not-allowed}\n  button.ghost{background:transparent}\n  .stat{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed var(--line);font-size:13px}\n  .stat:last-child{border-bottom:0}\n  .stat span:first-child{color:var(--muted)}\n  .dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:var(--muted)}\n  .dot.ok{background:var(--ok)}.dot.warn{background:var(--warn)}.dot.bad{background:var(--bad)}\n  .jobs{display:flex;flex-direction:column;gap:10px}\n  .job{border:1px solid var(--line);border-radius:12px;padding:12px;background:var(--panel2)}\n  .job .top{display:flex;gap:10px;align-items:center;justify-content:space-between}\n  .chip{font-size:11px;padding:2px 8px;border-radius:999px;background:#26304a;color:#c9d4ef}\n  .chip.SUCCEEDED{background:#123d2c;color:#7ef0b6}.chip.FAILED{background:#3d1616;color:#ff9d9d}\n  .chip.RUNNING{background:#2b2f16;color:#f5d76e}.chip.PENDING{background:#1d2a45;color:#9db8ff}\n  .bar{height:6px;background:#0e1220;border-radius:999px;overflow:hidden;margin-top:8px}\n  .bar>i{display:block;height:100%;background:linear-gradient(90deg,#5b8cff,#3ddc97);width:0}\n  .meta{color:var(--muted);font-size:12px;margin-top:6px;white-space:pre-wrap;word-break:break-word}\n  .err{color:#ff9d9d}\n  img.out{max-width:100%;border-radius:10px;margin-top:10px;border:1px solid var(--line)}\n  .toast{position:fixed;right:18px;bottom:18px;max-width:380px;background:#2a1a1a;border:1px solid #5a2a2a;color:#ffd7d7;padding:10px 14px;border-radius:10px;display:none}\n  .hint{color:var(--muted);font-size:12px;margin-top:8px}\n  .hidden{display:none}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <h1>Anima 工作站</h1>\n    <span class=\"badge\" id=\"build\">v2</span>\n    <span class=\"badge\" id=\"conn\">未連線</span>\n    <span style=\"flex:1\"></span>\n    <button class=\"ghost\" id=\"settingsBtn\">設定</button>\n  </header>\n\n  <section class=\"card hidden\" id=\"loginCard\" style=\"margin-bottom:16px\">\n    <h2>連線</h2>\n    <label>Relay 網址</label>\n    <input id=\"url\" type=\"text\" placeholder=\"https://anima.xxx.workers.dev\" readonly>\n    <label>Client Key（存在此瀏覽器，不會上傳到別處）</label>\n    <input id=\"key\" type=\"password\" placeholder=\"貼上 client.key 內容\">\n    <div class=\"hint\">網址會自動帶入目前網域；金鑰只存在這台裝置的 localStorage，可按「清除」移除。</div>\n    <div style=\"margin-top:12px;display:flex;gap:8px\">\n      <button class=\"primary\" id=\"save\">儲存並連線</button>\n      <button id=\"clear\">清除</button>\n    </div>\n  </section>\n\n  <div class=\"grid\">\n    <div>\n      <section class=\"card\">\n        <h2>系統狀態</h2>\n        <div class=\"stat\"><span>Relay</span><span id=\"s-relay\">—</span></div>\n        <div class=\"stat\"><span>VM 代理</span><span id=\"s-agent\">—</span></div>\n        <div class=\"stat\"><span>執行後端</span><span id=\"s-backend\">—</span></div>\n        <div class=\"stat\"><span>後端模式</span>\n          <select id=\"modeSel\" style=\"background:var(--card2);color:var(--tx);border:1px solid #33406e;border-radius:8px;padding:2px 6px;font-size:12px\">\n            <option value=\"auto\">自動</option>\n            <option value=\"local\">本地 Python（Nitro5）</option>\n            <option value=\"colab\">Colab CLI</option>\n            <option value=\"vm\">VM（Codex）</option>\n          </select></div>\n        <div class=\"stat\" id=\"colabRow\" style=\"display:none\"><span>Colab 網址</span>\n          <input id=\"colabUrl\" placeholder=\"https://xxxx.trycloudflare.com\" style=\"background:var(--card2);color:var(--tx);border:1px solid #33406e;border-radius:8px;padding:2px 6px;font-size:12px;width:170px\"></div>\n        <div class=\"stat\"><span>模型</span><span id=\"s-model\">—</span></div>\n        <div class=\"stat\"><span>佇列</span><span id=\"s-queue\">—</span></div>\n        <div class=\"stat\"><span>CPU / 記憶體</span><span id=\"s-res\">—</span></div>\n        <div class=\"stat\"><span>GPU / VRAM</span><span id=\"s-gpu\">—</span></div>\n        <canvas id=\"res-chart\" width=\"300\" height=\"56\" style=\"width:100%;height:56px;margin-top:4px\"></canvas>\n        <div class=\"stat\"><span>最近錯誤</span><span id=\"s-err\" class=\"err\">—</span></div>\n        <div class=\"hint\" id=\"s-policy\"></div>\n      </section>\n\n      <section class=\"card\" style=\"margin-top:16px\">\n        <h2>產生圖片</h2>\n        <label>提示詞</label>\n        <select id=\"recent\" style=\"margin-bottom:6px\"><option value=\"\">最近用過的提示詞…</option></select>\n        <textarea id=\"prompt\" placeholder=\"描述你想要的畫面…\"></textarea>\n        <label>模型（可輸入任意 HF repo id，後端自動下載）</label>\n      <select id=\"f-model\" style=\"margin-bottom:6px;background:var(--card2);color:var(--tx);border:1px solid #33406e;border-radius:8px;padding:6px;width:100%\"></select>\n      <input id=\"f-model-custom\" style=\"display:none;margin-bottom:6px;background:var(--card2);color:var(--tx);border:1px solid #33406e;border-radius:8px;padding:6px;width:100%\" placeholder=\"輸入 HF repo id 或模型檔名\">\n      <label id=\"base-row\" style=\"display:none;margin-bottom:6px\">底模（自訂模型用）\n        <select id=\"f-base\" style=\"background:var(--card2);color:var(--tx);border:1px solid #33406e;border-radius:8px;padding:6px;width:100%\">\n          <option value=\"\">自動判斷</option>\n          <option value=\"sdxl-single\">SDXL 單檔（safetensors/ckpt 微調）</option>\n          <option value=\"generic\">diffusers 標準管線</option>\n          <option value=\"anima\">Anima 系（modular + remote code）</option>\n        </select>\n      </label>\n      <datalist id=\"modelList\"></datalist>\n      <label>LoRA</label>\n      <select id=\"f-lora\" style=\"margin-bottom:6px\"></select>\n      <label style=\"display:flex;align-items:center;gap:6px;margin-bottom:6px\" id=\"turbo-row\"><input type=\"checkbox\" id=\"f-turbo\"> Turbo LoRA（快，8 步；取消則標準 30 步）<span id=\"turbo-note\" style=\"color:#8a93b8;font-size:12px\"></span></label>\n      <label>負面提示詞</label>\n        <input id=\"neg\" type=\"text\" value=\"low quality, blurry\">\n        <div class=\"row\">\n          <div>\n            <label>尺寸</label>\n            <select id=\"size\">\n              <option value=\"512\" selected>512 × 512（1:1）</option>\n              <option value=\"768\">768 × 768（1:1）</option>\n              <option value=\"1024\">1024 × 1024（1:1）</option>\n              <option value=\"1024x576\">1024 × 576（16:9）</option>\n              <option value=\"768x448\">768 × 448（16:9）</option>\n              <option value=\"custom\">自訂</option>\n            </select>\n          </div>\n          <div>\n            <label>步數</label>\n            <input id=\"steps\" type=\"number\" min=\"1\" max=\"20\" value=\"8\">\n          </div>\n        </div>\n        <div class=\"row hidden\" id=\"customRow\">\n          <div><label>寬</label><input id=\"w\" type=\"number\" value=\"512\" step=\"32\" min=\"128\" max=\"1024\"></div>\n          <div><label>高</label><input id=\"h\" type=\"number\" value=\"512\" step=\"32\" min=\"128\" max=\"1024\"></div>\n        </div>\n        <div class=\"row\">\n          <div><label>種子</label><input id=\"seed\" type=\"number\" value=\"42\" min=\"0\"></div>\n          <div><label>張數</label><input id=\"batch\" type=\"number\" min=\"1\" max=\"4\" value=\"1\"></div>\n          <div style=\"display:flex;align-items:flex-end\"><button id=\"rand\" style=\"width:100%\">隨機</button></div>\n        </div>\n        <div style=\"margin-top:14px\"><button class=\"primary\" id=\"go\" style=\"width:100%\">送出</button></div>\n        <div class=\"hint\" id=\"formHint\">寬高必須是 32 的倍數，128–1024。</div>\n      </section>\n    </div>\n\n    <div>\n      <section class=\"card\">\n        <h2>任務</h2>\n        <div class=\"jobs\" id=\"jobs\"><div class=\"meta\">尚無任務。送出後會顯示在這裡。</div></div>\n      </section>\n    </div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst LS = { url:\"anima.url\", key:\"anima.key\", jobs:\"anima.jobs\" };\nlet cfg = { url: localStorage.getItem(LS.url) || (location.protocol===\"https:\"?location.origin:\"\"), key: localStorage.getItem(LS.key) || \"\" };\nlet jobs = JSON.parse(localStorage.getItem(LS.jobs) || \"[]\");\nlet timer = null;\n\n// ---- 本機圖片快取（伺服器只保留 24h，DO 換實例也會清空）----\nfunction idb(){return new Promise((res,rej)=>{const r=indexedDB.open(\"anima\",1);r.onupgradeneeded=()=>r.result.createObjectStore(\"images\");r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}\nasync function idbGet(k){try{const db=await idb();return await new Promise((res,rej)=>{const q=db.transaction(\"images\",\"readonly\").objectStore(\"images\").get(k);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error);});}catch(e){return null;}}\nasync function idbPut(k,v){try{const db=await idb();await new Promise((res,rej)=>{const t=db.transaction(\"images\",\"readwrite\");t.objectStore(\"images\").put(v,k);t.oncomplete=res;t.onerror=()=>rej(t.error);});}catch(e){}}\nasync function idbDel(k){try{const db=await idb();await new Promise((res)=>{const t=db.transaction(\"images\",\"readwrite\");t.objectStore(\"images\").delete(k);t.oncomplete=res;});}catch(e){}}\n\nfunction toast(msg, ms=6000){\n  const t = $(\"toast\"); t.textContent = msg; t.style.display = \"block\";\n  clearTimeout(t._t); t._t = setTimeout(()=> t.style.display=\"none\", ms);\n}\nfunction apiBase(){ return cfg.url.replace(/\\/+$/,\"\"); }\nasync function api(path, opts={}){\n  if(!cfg.key) throw new Error(\"尚未設定金鑰\");\n  const res = await fetch(apiBase()+path, { ...opts, headers:{ \"Authorization\":\"Bearer \"+cfg.key, \"Content-Type\":\"application/json\", ...(opts.headers||{}) } });\n  if(!res.ok){\n    let msg = \"\";\n    try { const j = await res.json(); msg = j.error || \"\"; } catch(e){}\n    const map = { 401:\"金鑰不正確\", 403:\"沒有權限\", 404:\"找不到任務\", 409:\"任務狀態衝突\", 413:\"內容太大\", 422:\"參數不合法\", 429:\"佇列已滿或達到每日上限\", 503:\"VM 代理離線，請稍後再試\" };\n    throw new Error(map[res.status] || (msg || (\"HTTP \"+res.status)));\n  }\n  return res;\n}\n\nfunction setConn(state, text){ const el=$(\"conn\"); el.textContent=text; el.style.color = state===\"ok\"?\"var(--ok)\":state===\"warn\"?\"var(--warn)\":state===\"bad\"?\"var(--bad)\":\"var(--muted)\"; }\n\nasync function refresh(){\n  if(!cfg.url || !cfg.key){ $(\"loginCard\").classList.remove(\"hidden\"); setConn(\"idle\",\"未連線\"); return; }\n  try{\n    const h = await (await api(\"/healthz\")).json();\n    setConn(\"ok\",\"已連線\");\n    $(\"s-relay\").innerHTML = '<span class=\"dot ok\"></span>READY';\n    const age = h.agent_age_seconds;\n    const online = h.agent_recent;\n    $(\"s-agent\").innerHTML = online\n      ? `<span class=\"dot ${age!=null && age>90?\"warn\":\"ok\"}\"></span>在線${age!=null?`（${age}s 前）`:\"\"}`\n      : '<span class=\"dot bad\"></span>離線';\n    $(\"s-backend\").innerHTML = online\n      ? '<span class=\"dot ok\"></span>VM（Codex 雲端）'\n      : (h.fallback_configured\n        ? '<span class=\"dot warn\"></span>PC fallback（本機 ComfyUI 出圖）'\n        : '<span class=\"dot bad\"></span>無後端（任務將失敗）');\n    const m = h.agent?.system?.model;\n    $(\"s-model\").textContent = m ? `${m.state}${m.lora_name?\" · \"+m.lora_name:\"\"}` : \"—\";\n    $(\"s-queue\").textContent = `待處理 ${h.pending ?? 0} / 執行中 ${h.running ?? 0}`;\n    $(\"s-policy\").dataset.fallback = h.fallback_configured ? \"1\" : \"0\";\n    const sysv = h.agent?.system || h.system || h.backend?.system || null;\n    const cpu = sysv?.cpu?.usage_percent ?? sysv?.cpu?.quota_usage_percent ?? null;\n    const memU = Number(sysv?.memory?.used ?? (sysv?.memory?.used_bytes ? sysv.memory.used_bytes/1e9 : NaN));\n    const memT = Number(sysv?.memory?.total ?? (sysv?.memory?.limit_bytes ? sysv.memory.limit_bytes/1e9 : NaN));\n    const gpu = sysv?.gpu || null;\n    $(\"s-res\").textContent = (cpu != null || !isNaN(memT)) ? `${cpu ?? \"?\"}% · ${isNaN(memU)?\"?\":(memU/1.0737).toFixed(1)}/${isNaN(memT)?\"?\":Math.round(memT/1.0737)}G` : \"—\";\n    $(\"s-gpu\").textContent = gpu ? `${gpu.util_percent}% · ${gpu.vram_used}/${gpu.vram_total}G` : \"—\";\n    drawResChart(sysv?.history || []);\n    $(\"s-err\").textContent = h.last_error || \"—\";\n    const be = h.backend || {};\n    if(be.online !== undefined && !online){\n      $(\"s-backend\").innerHTML = be.online\n        ? '<span class=\"dot ok\"></span>PC fallback（diffusers，在線）'\n        : '<span class=\"dot bad\"></span>PC fallback（離線）';\n    }\n    const models = (h.backend && h.backend.models) || [];\n    const loras = (h.backend && h.backend.loras) || [];\n    const CURATED = [\"cagliostrolab/animagine-xl-4.0\",\n                     \"OnomaAIResearch/Illustrious-XL-v2.0\",\n                     \"circlestone-labs/Anima\",\n                     \"ricecake/Krea-2-Anime-tuned-Raw\",\n                     \"ricecake/Krea-2-Anime-tuned-Turbo\",\n                     \"Qwen/Qwen-Image\",\n                     \"OpenMOSS-Team/MOSS-Image-Base\",\n                     \"stabilityai/stable-diffusion-xl-base-1.0\"];\n    const CURATED_NOTE = {\"circlestone-labs/Anima\": \"（架構暫不支援）\",\n                          \"ricecake/Krea-2-Anime-tuned-Raw\": \"（需 HF 授權）\",\n                          \"ricecake/Krea-2-Anime-tuned-Turbo\": \"（需 HF 授權）\",\n                          \"OpenMOSS-Team/MOSS-Image-Base\": \"（架構暫不支援）\"};\n    const all = [...new Set([...models, ...CURATED])];\n    const fm = $(\"f-model\"), fmc = $(\"f-model-custom\"), fl = $(\"f-lora\"), dl = $(\"modelList\");\n    if(fm.options.length !== all.length + 1){\n      fm.innerHTML = all.map(m=>`<option value=\"${m}\">${m.includes(\"/\")?\"HF: \"+m:m}${models.includes(m)?\" ✓\":\"\"}${CURATED_NOTE[m]||\"\"}</option>`).join(\"\") + '<option value=\"__custom__\">自訂（輸入 HF repo id…）</option>';\n      dl.innerHTML = all.map(m=>`<option value=\"${m}\"></option>`).join(\"\");\n      if(!fm.value || ![...fm.options].some(o=>o.value===fm.value)) fm.value = models[0] || CURATED[0];\n      fmc.style.display = fm.value === \"__custom__\" ? \"\" : \"none\";\n    }\n    fm.onchange = () => { fmc.style.display = fm.value === \"__custom__\" ? \"\" : \"none\"; $(\"base-row\").style.display = fmc.style.display; syncTurbo(); };\n    const isAnimaModel = () => /anima|janima/i.test(fm.value === \"__custom__\" ? fmc.value : fm.value);\n    function syncTurbo(){\n      const ft = $(\"f-turbo\"), ok = isAnimaModel();\n      ft.disabled = !ok;\n      $(\"turbo-note\").textContent = ok ? \"\" : \"（僅 Anima 系模型可用）\";\n      if(!ok) ft.checked = false;\n    }\n    fmc.addEventListener(\"input\", syncTurbo);\n    syncTurbo();\n    if(fl.options.length !== loras.length + 1){\n      fl.innerHTML = '<option value=\"\">不用 LoRA</option>' + loras.map(l=>`<option>${l}</option>`).join(\"\");\n    }\n    if(h.policy) $(\"s-policy\").textContent = `代理逾時 ${h.policy.soft_queue_seconds}s 排隊 / ${h.policy.hard_reject_seconds}s 拒絕 · 租約 ${h.policy.lease_seconds/60} 分`;\n  }catch(e){\n    setConn(\"bad\", \"連線失敗\");\n    toast(e.message);\n  }\n  await refreshJobs();\n}\n\nfunction fmt(ts){ return ts ? new Date(ts).toLocaleTimeString() : \"—\"; }\n\nfunction drawResChart(hist){\n  const c = document.getElementById(\"res-chart\");\n  if(!c || !hist || hist.length < 2) return;\n  const ctx = c.getContext(\"2d\");\n  ctx.clearRect(0, 0, c.width, c.height);\n  const series = [[\"cpu\", \"#7aa2ff\"], [\"mem\", \"#67d38b\"], [\"gpu\", \"#f7a76c\"], [\"vram\", \"#e06c9f\"]];\n  for(const [key, color] of series){\n    const pts = hist.map((p, i) => [i / (hist.length - 1) * c.width, c.height - (p[key] ?? 0) / 100 * c.height]);\n    ctx.beginPath();\n    pts.forEach((p, i) => i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]));\n    ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.stroke();\n  }\n}\n\nfunction renderJob(j){\n  const p = j.request || {};\n  const prog = j.progress;\n  const pct = prog && prog.total ? Math.round(100*prog.step/prog.total) : (j.status===\"SUCCEEDED\"?100:0);\n  const stageMap = { ENCODING:\"編碼提示詞\", DENOISING:\"去噪\", DECODING:\"解碼\", SAVING:\"存檔\" };\n  const el = document.createElement(\"div\");\n  el.className = \"job\";\n  el.innerHTML = `\n    <div class=\"top\">\n      <div><span class=\"chip ${j.status}\">${({PENDING:\"排隊中\",RUNNING:\"執行中\",SUCCEEDED:\"完成\",FAILED:\"失敗\"})[j.status]||j.status}</span>${j.backend===\"fallback\"?'<span class=\"chip\">備援</span>':\"\"}\n      <span class=\"meta\">${p.width}×${p.height} · ${p.steps} 步 · seed ${p.seed}</span></div>\n      <span class=\"meta\">${fmt(j.created)}</span>\n    </div>\n    <div class=\"meta\">${(p.prompt||\"\").slice(0,180)}</div>\n    ${j.metadata?`<div class=\"meta\">${[j.metadata.engine,j.metadata.model,j.metadata.duration_seconds?j.metadata.duration_seconds+\"s\":\"\"].filter(Boolean).join(\" · \")}</div>`:\"\"}\n    ${j.status===\"RUNNING\"&&prog?`<div class=\"bar\"><i style=\"width:${pct}%\"></i></div><div class=\"meta\">${stageMap[prog.stage]||prog.stage} ${prog.step}/${prog.total} · ${prog.elapsed_seconds?.toFixed(1)}s</div>`:\"\"}\n    ${j.error?`<div class=\"meta err\">${j.error}</div>`:\"\"}\n    ${j.status===\"PENDING\"?'<button class=\"ghost\" data-cancel=\"'+j.id+'\" style=\"padding:2px 10px;margin-top:8px\">取消</button>':\"\"}\n  `;\n  const cancelBtn = el.querySelector(\"[data-cancel]\");\n  if(cancelBtn) cancelBtn.onclick = async () => {\n    cancelBtn.disabled = true;\n    try { await api(\"/v1/jobs/\"+j.id, { method:\"DELETE\" }); await refreshJobs(); }\n    catch(e){ toast(e.message); cancelBtn.disabled = false; }\n  };\n  if(j.status===\"SUCCEEDED\"){\n    const img = document.createElement(\"img\");\n    img.className=\"out\"; img.alt=\"生成結果\";\n    el.appendChild(img);\n    const dl = document.createElement(\"a\");\n    dl.textContent = \"下載 PNG\"; dl.className = \"chip\"; dl.style.cssText = \"display:inline-block;margin-top:8px;text-decoration:none\";\n    dl.download = j.id + \".png\";\n    img.after(dl);\n    if(j._imgUrl){ img.src = j._imgUrl; dl.href = j._imgUrl; }\n    else {\n      idbGet(j.id).then(cached=>{\n        if(cached){ j._imgUrl = URL.createObjectURL(cached); img.src = j._imgUrl; dl.href = j._imgUrl; return; }\n        api(`/v1/jobs/${j.id}/image`).then(r=>r.blob()).then(b=>{\n          idbPut(j.id,b);\n          j._imgUrl = URL.createObjectURL(b); img.src = j._imgUrl; dl.href = j._imgUrl;\n        }).catch(()=>{ img.remove(); });\n      });\n    }\n  }\n  return el;\n}\n\nfunction renderExpired(id, blob){\n  const el = document.createElement(\"div\");\n  el.className = \"job\";\n  el.innerHTML = `<div class=\"top\"><div><span class=\"chip\">已過期</span>\n    <span class=\"meta\">伺服器紀錄已清除（保留 24 小時）</span></div>\n    <button class=\"ghost\" data-del=\"${id}\" style=\"padding:2px 10px\">刪除</button></div>`;\n  if(blob){ const img=document.createElement(\"img\"); img.className=\"out\"; img.src=URL.createObjectURL(blob); el.appendChild(img); }\n  else { const p=document.createElement(\"div\"); p.className=\"meta\"; p.textContent=\"本機也沒有快取\"; el.appendChild(p); }\n  el.querySelector(\"[data-del]\").onclick = async () => { await idbDel(id); jobs = jobs.filter(x=>x!==id); localStorage.setItem(LS.jobs, JSON.stringify(jobs)); refreshJobs(); };\n  return el;\n}\n\nasync function refreshJobs(force){\n  const box = $(\"jobs\");\n  let server = null;\n  try { server = (await (await api(\"/v1/jobs?limit=20\")).json()).jobs; } catch(e) { server = null; }\n\n  if(server){\n    const ids = server.map(j => j.id);\n    const sig = JSON.stringify(server.map(j => [j.id, j.status]));\n    if(!force && (window.scrollY > 40 || box.matches(\":hover\"))) return;\n    jobs = [...ids, ...jobs.filter(id => !ids.includes(id))].slice(0, 40);\n    localStorage.setItem(LS.jobs, JSON.stringify(jobs));\n    box.innerHTML = \"\";\n    if(!server.length) box.innerHTML = '<div class=\"meta\">尚無任務。送出後會顯示在這裡。</div>';\n    for(const j of server) box.appendChild(renderJob(j));\n    const localOnly = jobs.filter(id => !ids.includes(id)).slice(0, 12);\n    for(const id of localOnly){ const blob = await idbGet(id); box.appendChild(renderExpired(id, blob)); }\n    return;\n  }\n\n  if(!jobs.length){ box.innerHTML = '<div class=\"meta\">尚無任務。送出後會顯示在這裡。</div>'; return; }\n  const before = jobs.slice(0,12);\n  box.innerHTML = \"\";\n  const stillThere = [];\n  for(const id of before){\n    let j = null;\n    try { j = await (await api(\"/v1/jobs/\"+id)).json(); }\n    catch(e){\n      const blob = await idbGet(id);\n      box.appendChild(renderExpired(id, blob));\n      stillThere.push(id);\n      continue;\n    }\n    stillThere.push(id);\n    box.appendChild(renderJob(j));\n  }\n  jobs = [...stillThere, ...jobs.slice(12)];\n  localStorage.setItem(LS.jobs, JSON.stringify(jobs));\n}\n\nasync function submit(){\n  const prompt = $(\"prompt\").value.trim();\n  if(!prompt){ toast(\"請先輸入提示詞\"); return; }\n  let w,$h;\n  const sizeSel = $(\"size\").value;\n  let width, height;\n  if(sizeSel===\"custom\"){ width=+$(\"w\").value; height=+$(\"h\").value; }\n  else if(sizeSel.includes(\"x\")){ const [a,b]=sizeSel.split(\"x\"); width=+a; height=+b; }\n  else { width=height=+sizeSel; }\n  for(const v of [width,height]) if(v<128||v>1024||v%32){ toast(\"寬高必須是 128–1024 且為 32 的倍數\"); return; }\n  const steps = +$(\"steps\").value;\n  const batch = Math.max(1, Math.min(4, +$(\"batch\").value || 1));\n  const baseSeed = +$(\"seed\").value;\n  $(\"go\").disabled = true;\n  let queued = 0, offline = false;\n  try{\n    for(let i=0;i<batch;i++){\n      const model = $(\"f-model\").value === \"__custom__\" ? ($(\"f-model-custom\").value || \"\").trim() : $(\"f-model\").value;\n      const baseFamily = model && $(\"f-model\").value === \"__custom__\" ? ($(\"f-base\") ? $(\"f-base\").value : \"\") : \"\";\n      const body = { prompt, negative_prompt: $(\"neg\").value, width, height, steps, seed: baseSeed + i , model, base_family: baseFamily, lora: $(\"f-lora\").value, turbo: $(\"f-turbo\").checked};\n      const r = await api(\"/v1/generations\", { method:\"POST\", body: JSON.stringify(body) });\n      const j = await r.json();\n      jobs.unshift(j.id); localStorage.setItem(LS.jobs, JSON.stringify(jobs));\n      queued++;\n      if(j.queued_while_agent_offline) offline = true;\n      await refreshJobs();\n    }\n    rememberPrompt(prompt);\n    if(queued>1) toast(`已送出 ${queued} 張（seed ${baseSeed}–${baseSeed+queued-1}）`, 5000);\n    if(offline) toast(\"VM 代理目前離線，任務已排隊（10 分鐘內未執行會自動失敗）\", 8000);\n    refresh();\n  }catch(e){ toast(e.message, 8000); }\n  finally{ $(\"go\").disabled = false; }\n}\n\nconst LS_PROMPTS = \"anima.prompts\";\nfunction loadPrompts(){ try{ return JSON.parse(localStorage.getItem(LS_PROMPTS)||\"[]\"); }catch(e){ return []; } }\nfunction rememberPrompt(p){\n  const list = loadPrompts().filter(x=>x!==p); list.unshift(p);\n  localStorage.setItem(LS_PROMPTS, JSON.stringify(list.slice(0,20)));\n  renderRecent();\n}\nfunction renderRecent(){\n  const sel = $(\"recent\"); const list = loadPrompts();\n  sel.innerHTML = '<option value=\"\">最近用過的提示詞…</option>' + list.map((p,i)=>`<option value=\"${i}\">${p.slice(0,60).replace(/</g,\"&lt;\")}</option>`).join(\"\");\n  sel.onchange = () => { const i = sel.value; if(i!==\"\"){ $(\"prompt\").value = loadPrompts()[+i]; sel.value=\"\"; } };\n}\n\nfunction applyCfg(){\n  $(\"url\").value = cfg.url; $(\"key\").value = cfg.key;\n  $(\"loginCard\").classList.toggle(\"hidden\", !!(cfg.url && cfg.key));\n}\n$(\"save\").onclick = () => {\n  const url = $(\"url\").value.trim(); const key = $(\"key\").value.trim();\n  if(!/^https:\\/\\//.test(url)){ toast(\"網址必須是 https://\"); return; }\n  if(key.length < 32){ toast(\"金鑰長度不正確\"); return; }\n  cfg = { url, key }; localStorage.setItem(LS.url,url); localStorage.setItem(LS.key,key);\n  $(\"loginCard\").classList.add(\"hidden\"); refresh();\n};\n$(\"clear\").onclick = () => { localStorage.removeItem(LS.url); localStorage.removeItem(LS.key); cfg={url:\"\",key:\"\"}; applyCfg(); setConn(\"idle\",\"未連線\"); };\n$(\"settingsBtn\").onclick = () => $(\"loginCard\").classList.toggle(\"hidden\");\n$(\"size\").onchange = e => $(\"customRow\").classList.toggle(\"hidden\", e.target.value!==\"custom\");\n$(\"rand\").onclick = () => $(\"seed\").value = Math.floor(Math.random()*4294967295);\n$(\"go\").onclick = submit;\n\n// 支援 #key=<client key> 一次性帶入（掃 QR 用），帶入後立刻從網址移除\n(function adoptHash(){\n  const h = location.hash.replace(/^#/,\"\");\n  if(!h) return;\n  const params = new URLSearchParams(h);\n  const k = params.get(\"key\");\n  if(k && k.length>=32){\n    cfg.key = k;\n    cfg.url = params.get(\"url\") || cfg.url;\n    localStorage.setItem(LS.key, cfg.key);\n    localStorage.setItem(LS.url, cfg.url);\n    history.replaceState(null, \"\", location.pathname);\n  }\n})();\n\napplyCfg();\nrenderRecent();\nrefresh();\n$(\"f-turbo\").addEventListener(\"change\", e=>{ const st=$(\"steps\") || document.querySelector(\"[id*=step]\"); if(st){ st.value = e.target.checked ? 8 : 30; } });\nasync function loadMode(){\n  try{\n    const m = await (await api(\"/v1/backend\")).json();\n    $(\"modeSel\").value = m.mode || \"auto\";\n    $(\"colabUrl\").value = m.colab_url || \"\";\n    $(\"colabRow\").style.display = m.mode === \"colab\" ? \"flex\" : \"none\";\n  }catch(e){}\n}\n$(\"modeSel\").addEventListener(\"change\", async e=>{\n  const body = {mode: e.target.value};\n  if(e.target.value === \"colab\" && $(\"colabUrl\").value) body.colab_url = $(\"colabUrl\").value.trim();\n  const r = await api(\"/v1/backend\", {method:\"POST\", body: JSON.stringify(body)});\n  toast(r.mode ? \"後端模式 → \" + r.mode : \"設定失敗\");\n  if(r.colab_url !== undefined) $(\"colabUrl\").value = r.colab_url;\n});\n$(\"colabUrl\").addEventListener(\"change\", async e=>{\n  const r = await api(\"/v1/backend\", {method:\"POST\", body: JSON.stringify({mode:\"colab\", colab_url:e.target.value.trim()})});\n  toast(r.ok ? \"Colab 網址已儲存\" : \"儲存失敗\");\n});\nloadMode();\ntimer = setInterval(()=>{ if(cfg.key && !document.hidden) refresh(); }, 4000);\nsetInterval(()=>{ if(cfg.key && !document.hidden && (window.scrollY <= 40) && !document.querySelector(\".bar\")) refreshJobs(true); }, 4000);\n</script>\n</body>\n</html>\n";
